package sdp

// EventPayload is an exported alias for the unexported isEvent_Payload oneof
// interface generated by protoc-gen-go for Event.payload (declared in
// brent.pb.go). It lets external packages declare a parameter of the oneof
// variant type while preserving the compile-time guarantee that only generated
// Event payload wrappers can satisfy it.
type EventPayload = isEvent_Payload
